package com.tripmateai.controller; import com.tripmateai.dto.request.booking.*; import com.tripmateai.dto.response.*; import com.tripmateai.dto.response.booking.*; import com.tripmateai.service.BookingService; import com.tripmateai.util.ResponseUtils; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/trips/{tripId}/bookings") @RequiredArgsConstructor public class BookingController {private final BookingService service; @PostMapping public ResponseEntity<ApiResponse<BookingResponse>> create(@PathVariable Long tripId,@Valid @RequestBody CreateBookingRequest r){return ResponseUtils.created(service.create(tripId,r),"Booking created");} @GetMapping public ResponseEntity<ApiResponse<List<BookingResponse>>> list(@PathVariable Long tripId){return ResponseUtils.success(service.list(tripId),"Bookings retrieved");} @GetMapping("/{bookingId}") public ResponseEntity<ApiResponse<BookingResponse>> get(@PathVariable Long tripId,@PathVariable Long bookingId){return ResponseUtils.success(service.get(tripId,bookingId),"Booking retrieved");} @PutMapping("/{bookingId}") public ResponseEntity<ApiResponse<BookingResponse>> update(@PathVariable Long tripId,@PathVariable Long bookingId,@Valid @RequestBody UpdateBookingRequest r){return ResponseUtils.success(service.update(tripId,bookingId,r),"Booking updated");} @DeleteMapping("/{bookingId}") public ResponseEntity<ApiResponse<Void>> delete(@PathVariable Long tripId,@PathVariable Long bookingId){service.delete(tripId,bookingId);return ResponseUtils.success(null,"Booking deleted");}}
